CREATE INDEX idx_payments_cheques
  ON payments (firm_id, cheque_status, cheque_date_utc)
  WHERE cheque_no IS NOT NULL;

CREATE UNIQUE INDEX idx_uconv_firmwide
  ON unit_conversions (firm_id, from_unit_id, to_unit_id)
  WHERE item_id IS NULL AND deleted_at_utc IS NULL;

CREATE UNIQUE INDEX idx_uconv_peritem
  ON unit_conversions (firm_id, item_id, from_unit_id, to_unit_id)
  WHERE item_id IS NOT NULL AND deleted_at_utc IS NULL;
